import express, { NextFunction, Request, Response } from "express";
import { InsufficientStockError, NotFoundError, OrderService } from "../application/order-service";
import { OrderItem, orderStates, OrderState } from "../domain/order";
import { DomainError } from "../domain/product";
import { InMemoryFulfilmentStore } from "./in-memory-store";

export function createApp(service = new OrderService(new InMemoryFulfilmentStore())): express.Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_request, response) => response.json({ status: "ok" }));
  app.post("/products", (request, response, next) => {
    try {
      const body = objectBody(request);
      const product = service.addProduct(stringField(body, "id"), stringField(body, "name"), numberField(body, "stock"));
      response.status(201).json(product);
    } catch (error) { next(error); }
  });
  app.get("/products", (_request, response) => response.json(service.listProducts()));

  app.post("/orders", (request, response, next) => {
    try {
      const body = objectBody(request);
      const items = parseItems(body.items);
      response.status(201).json(service.placeOrder(items));
    } catch (error) { next(error); }
  });
  app.get("/orders", (request, response, next) => {
    try { response.json(service.listOrders(parseState(request.query.state))); } catch (error) { next(error); }
  });
  app.get("/orders/:id", (request, response, next) => {
    try { response.json(service.getOrder(request.params.id)); } catch (error) { next(error); }
  });
  app.post("/orders/:id/transition", (request, response, next) => {
    try {
      const body = objectBody(request);
      response.json(service.transitionOrder(request.params.id, parseState(body.state, true)!));
    } catch (error) { next(error); }
  });
  app.post("/orders/:id/cancel", (request, response, next) => {
    try { response.json(service.cancelOrder(request.params.id)); } catch (error) { next(error); }
  });

  app.use((error: unknown, _request: Request, response: Response, _next: NextFunction) => {
    if (error instanceof NotFoundError) return response.status(404).json({ error: error.message });
    if (error instanceof InsufficientStockError || error instanceof DomainError) return response.status(409).json({ error: error.message });
    if (error instanceof SyntaxError) return response.status(400).json({ error: "Invalid JSON" });
    return response.status(400).json({ error: "Invalid request" });
  });
  return app;
}

function objectBody(request: Request): Record<string, unknown> {
  if (typeof request.body !== "object" || request.body === null || Array.isArray(request.body)) throw new DomainError("Request body must be an object");
  return request.body as Record<string, unknown>;
}
function stringField(body: Record<string, unknown>, field: string): string {
  if (typeof body[field] !== "string") throw new DomainError(`${field} must be a string`);
  return body[field];
}
function numberField(body: Record<string, unknown>, field: string): number {
  if (typeof body[field] !== "number") throw new DomainError(`${field} must be a number`);
  return body[field];
}
function parseItems(value: unknown): OrderItem[] {
  if (!Array.isArray(value)) throw new DomainError("items must be an array");
  return value.map((value) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) throw new DomainError("Each item must be an object");
    const item = value as Record<string, unknown>;
    return { productId: stringField(item, "productId"), quantity: numberField(item, "quantity") };
  });
}
function parseState(value: unknown, required = false): OrderState | undefined {
  if (value === undefined && !required) return undefined;
  if (typeof value !== "string" || !orderStates.includes(value as OrderState)) throw new DomainError("Invalid order state");
  return value as OrderState;
}

